sys_variable_value.value:
(function execute(inputs, outputs) {
 if ((inputs.container_id != "" ) && (inputs.status_code == 200)) {
    outputs.status = "Success";
    outputs.container_info = inputs.response;
    outputs.container_details = JSON.parse(inputs.response);
  } else {
    outputs.status = "Error";
    outputs = new DockerErrorHandler().inspectContainerErrorHandler(inputs,outputs);       
  }
})(inputs, outputs);

